function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.fill();
  ctx.stroke();

  // stick figure reading book
  ctx.beginPath();
  ctx.arc(W/2, H/2+70, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2, H/2+90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2-30, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2+30, H/2+50);
  ctx.stroke();

  // lightbulb above head
  ctx.beginPath();
  ctx.arc(W/2, H/2+30+20*Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // lines representing wisdom
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2-50+30*Math.cos(t), H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2+50+30*Math.cos(t), H/2-50);
  ctx.stroke();

  ctx.restore();
}
